insert into public.support_resources (id, name, category, description, phone, website, chat_url, hours, coverage, eligibility, source_url, verified_on, verification) values
  ('ambulanse-113', 'Medisinsk nødtelefon 113', 'emergency', 'Ring 113 ved livsfare, akutt alvorlig sykdom eller skade – for eksempel brystsmerter, kramper, bevisstløshet eller mistanke om overdose.', '113', null, null, 'Døgnåpen', 'Hele landet', null, 'https://www.helsedirektoratet.no/veiledere/legevakt-og-legevaktsentral/telefoni-og-nodnett', '2026-10-08', 'search_extract'),
  ('legevakt-116117', 'Legevakt 116 117', 'urgent_medical', 'Når du trenger lege raskt, men det ikke er livstruende og fastlegen ikke er tilgjengelig. Du blir satt over til nærmeste legevakt.', '116 117', null, null, 'Døgnåpen', 'Hele landet', 'Alle som oppholder seg i Norge, også de uten fastlege', 'https://www.helsenorge.no/en/foreigners-in-norway/refugees-and-asylum-seekers/where-to-get-help/', '2026-10-08', 'search_extract'),
  ('politi-112', 'Politiets nødtelefon 112', 'emergency', 'Når det haster og liv, helse eller sikkerhet er truet av andre.', '112', null, null, 'Døgnåpen', 'Hele landet', null, 'https://www.helsedirektoratet.no/veiledere/legevakt-og-legevaktsentral/telefoni-og-nodnett', '2026-10-08', 'search_extract'),
  ('giftinformasjonen', 'Giftinformasjonen', 'drug_information', 'Råd på telefon hvis noen kan ha fått i seg noe giftig, også rusmidler eller for mye av et legemiddel. Ved alvorlige symptomer: ring 113.', '22 59 13 00', 'https://www.helsenorge.no/giftinformasjon/', null, 'Døgnåpen', 'Hele landet', null, 'https://www.helsenorge.no/giftinformasjon/rusmidler/', '2026-10-08', 'search_extract'),
  ('mental-helse-hjelpetelefonen', 'Mental Helse Hjelpetelefonen', 'crisis_line', 'Gratis telefon for alle som trenger noen å snakke med. Du kan være anonym.', '116 123', 'https://mentalhelse.no/fa-hjelp/hjelpetelefonen/', null, 'Døgnåpen', 'Hele landet', null, 'https://mentalhelse.no/fa-hjelp/hjelpetelefonen/', '2026-10-08', 'search_extract'),
  ('kirkens-sos', 'Kirkens SOS', 'crisis_line', 'Krisetelefon der du kan snakke anonymt når livet er vanskelig, også om selvmordstanker. Har også skriftlige tjenester.', '22 40 00 40', 'https://www.kirkens-sos.no/', 'https://soschat.no', 'Telefon: døgnåpen. Chat: begrensede åpningstider.', 'Hele landet', null, 'https://www.kirkens-sos.no/telefon', '2026-10-08', 'search_extract'),
  ('rusinfo', 'RUSinfo', 'drug_information', 'Anonym og gratis informasjonstjeneste om alkohol, narkotika og pengespill – på telefon eller chat. Ikke en nødtjeneste.', '915 08 588', 'https://rusinfo.no/', null, 'Hverdager kl. 11–18 (stengt 14.30–15). Stengt i helgene.', 'Hele landet', 'Alle, også pårørende', 'https://rusinfo.no/om-rustelefonen/', '2026-10-08', 'search_extract'),
  ('helsenorge-hjelp-med-rusproblemer', 'Helsenorge – hjelp med rusproblemer', 'treatment_access', 'Slik får du hjelp via fastlegen eller kommunens rustjeneste, og hvordan henvisning til spesialisert rusbehandling (TSB) fungerer.', null, 'https://www.helsenorge.no/rus-og-avhengighet/hjelp-med-rusproblemer/', null, null, 'Hele landet', 'Kommunale tjenester krever ikke at du er rusfri', 'https://www.helsenorge.no/rus-og-avhengighet/hjelp-med-rusproblemer/', '2026-10-08', 'search_extract'),
  ('helsenorge-velg-behandlingssted', 'Velg behandlingssted', 'treatment_access', 'Offentlig oversikt over behandlingssteder og ventetider, også for rus- og avhengighetsbehandling.', null, 'https://tjenester.helsenorge.no/velg-behandlingssted/behandlingssteder', null, null, 'Hele landet', null, 'https://tjenester.helsenorge.no/velg-behandlingssted/behandlingssteder', '2026-10-08', 'search_extract'),
  ('anonyme-narkomane-norge', 'Anonyme Narkomane (NA) Norge', 'peer_support', 'Selvhjelpsfellesskap for folk som vil slutte med rusmidler. Møter over hele landet, uten påmelding.', '905 29 359', 'https://nanorge.org/', null, 'Kontakttelefon alle dager kl. 10–22', 'Hele landet', null, 'https://nanorge.org/kontakt/', '2026-10-08', 'search_extract'),
  ('anonyme-alkoholikere-norge', 'Anonyme Alkoholikere (AA) Norge', 'peer_support', 'Selvhjelpsfellesskap for folk som vil slutte å drikke. Kontakttelefonen kan sette deg i kontakt med et medlem der du bor.', '911 77 770', 'https://www.anonymealkoholikere.no/', null, 'Hverdager kl. 11–15 og alle dager kl. 18–22', 'Hele landet', null, 'https://www.anonymealkoholikere.no/2/kontakt/', '2026-10-08', 'search_extract'),
  ('nalokson-overdoseforebygging', 'Forebygging av overdose (nalokson)', 'harm_reduction', 'Nalokson nesespray kan midlertidig reversere en opioidoverdose mens du venter på ambulanse. Helsenorge forklarer hvordan overdose kan forebygges.', null, 'https://www.helsenorge.no/rus-og-avhengighet/forebygging-av-overdose', null, null, 'Hele landet', null, 'https://www.helsenorge.no/rus-og-avhengighet/forebygging-av-overdose', '2026-10-08', 'search_extract'),
  ('nalokson-utdelingssteder', 'Naloksonprosjektet – utdelingssteder', 'harm_reduction', 'Kart over steder som deler ut nalokson nesespray med kort opplæring.', null, 'https://www.nalokson.uio.no/', null, null, 'Hele landet', 'Personer i risiko for opioidoverdose, pårørende og andre som kan komme til å se en overdose', 'https://www.nalokson.uio.no/nalokson/', '2026-10-08', 'search_extract'),
  ('ivareta-parorendetelefonen', 'Ivareta – Pårørendetelefonen', 'relatives', 'Gratis og anonym telefon for alle som er berørt av andres rusbruk. De som svarer er selv pårørende.', '800 40 567', 'https://www.ivareta.no/', null, 'Hverdager kl. 9–15, tirsdag også kl. 18–21', 'Hele landet', 'Pårørende og etterlatte', 'https://www.ivareta.no/deg-som-parorende/parorendetelefonen/', '2026-10-08', 'search_extract'),
  ('alarmtelefonen-116111', 'Alarmtelefonen for barn og unge', 'crisis_line', 'Gratis hjelpetelefon for barn og unge som opplever vold, overgrep eller omsorgssvikt – også når foreldre ruser seg.', '116 111', 'https://www.116111.no/', null, 'Telefon: døgnåpen', 'Hele landet', 'Barn og unge, og voksne som er bekymret for et barn', 'https://www.116111.no/omalarmtelefonen', '2026-10-08', 'search_extract'),
  ('rio', 'Rusmisbrukernes interesseorganisasjon (RIO)', 'user_organisation', 'Bruker- og interesseorganisasjon for folk med erfaring fra rusavhengighet og rusbehandling.', null, 'https://rio.no/', null, null, 'Hele landet', null, 'https://rio.no/personvern/', '2026-10-08', 'search_extract'),
  ('prolar-nett', 'proLAR Nett', 'user_organisation', 'Nasjonalt forbund for folk i legemiddelassistert rehabilitering (LAR).', null, 'https://prolar.no/', null, null, 'Hele landet', 'Personer i LAR', 'https://prolar.no/prosjekter-1/hepatitt-c', '2026-10-08', 'search_extract')
